// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2012, "4-5", [{"author":"К. Гилярова и И. Рубанов","question":"По шахматным полям ходит","choices":["царь","царевич","король","королевич","сапожник."],"key":"В","review":["Фигуры на доске","Вспомни, какую фигуру в шахматах защищают от мата. Её ход на свободное соседнее поле возможен, если оно не под ударом.","Эту фигуру называют королём. Царя, царевича, королевича и сапожника среди шахматных фигур нет."]},{"author":"К. Гилярова","question":"Царица произвела на свет сразу двоих детей. Она родила … .","choices":["двойку","двоицу","двойню","двушку","пару."],"key":"В","review":["Дети царицы","Царица родила двоих детей за один раз. Для двух детей из одних родов есть особое название.","Говорят «родила двойню». «Двойка» обычно обозначает цифру, отметку или что-то с номером два."]},{"author":"Е. Кац","question":"Никто никогда не видел","choices":["<em>стаю уток</em>","<em>стаю акул</em>","<em>стаю волков</em>","<em>стаю коров</em>","<em>стаю ворон</em>."],"key":"Г","review":["Как назвать группу","Утки, акулы, волки и вороны могут собираться в стаи. Проверь, как называют большую группу коров.","Коровы пасутся стадом. Поэтому выражение «стая коров» в обычной речи не употребляют."]},{"author":"Л. Фёдорова","question":"Винни-Пух учил таблицу умножения, но одно слово всё время употреблял некстати. Какое?","choices":["<em>однажды</em>","<em>дважды</em>","<em>трижды</em>","<em>четырежды</em>","<em>пятью</em>."],"key":"А","review":["Таблица Винни-Пуха","Прочитай привычные примеры «дважды два», «трижды три», «четырежды четыре» и «пятью пять». Эти слова обозначают умножение на два, три, четыре или пять.","Слово «однажды» в обычной речи означает «как-то раз». Для умножения на один говорят «один раз» или «умножить на один»."]},{"author":"И. Рубанов","question":"<em>... в темнице, ... в больнице, ... в очереди.</em>","choices":["<em>Лежать</em>, <em>сидеть</em>, <em>стоять</em>","<em>Лежать</em>, <em>стоять</em>, <em>сидеть</em>","<em>Сидеть</em>, <em>лежать</em>, <em>стоять</em>","<em>Сидеть</em>, <em>стоять</em>, <em>лежать</em>","<em>Стоять</em>, <em>лежать</em>, <em>сидеть</em>."],"key":"В","review":["Три места","Вспомни, как говорят о заключённом и больном. Один сидит в темнице, другой лежит в больнице.","Про ожидание в очереди говорят «стоять в очереди». Порядок слов выходит «сидеть, лежать, стоять»."]},{"author":"И. Иткин","question":"В каком слове нет того корня, который есть в четырёх остальных?","choices":["<em>ежевечерний</em>","<em>ежевика</em>","<em>ежегодный</em>","<em>еженедельник</em>","<em>ежеутренний</em>."],"key":"Б","review":["Начало «еже-»","Сравни слова «ежевечерний», «ежегодный», «еженедельник», «ежеутренний». Их часть «еже-» означает, что дело происходит каждый вечер, год, неделю или утро.","«Ежевика» — название ягоды. В нём «еже-» не означает «каждый», поэтому слово стоит отдельно."]},{"author":"А. Сомин","question":"<em>Серебристый</em> ... . Что скорее всего стоит на месте многоточия?","choices":["<em>полёт</em>","<em>налёт</em>","<em>прилёт</em>","<em>отлёт</em>","<em>подлёт</em>."],"key":"Б","review":["Серебристый след","«Серебристый» описывает цвет или блеск поверхности. Различи, где говорится о движении, а где о покрытии.","Полёт, прилёт, отлёт и подлёт — движения. Налёт — тонкий слой на поверхности, и он может быть серебристым."]},{"author":"И. Иткин и методкомиссия","question":"Даны наименования министерских должностей из литературных произведений:\n1) министр странных дел (Д. Пеннак, «Камо. Идея века»);\n2) министр иностранных дел (А. Некрасов, «Приключения капитана Врунгеля»);\n3) министр наружных дел (Л. Кассиль, «Кондуит и Швамбрания»).\nКакие из них существуют в действительности?","choices":["только 1","только 2","только 3","1 и 2","2 и 3."],"key":"Б","review":["Литературные министры","«Иностранный» значит связанный с другими странами. В правительстве есть министр, который занимается отношениями с ними.","Его должность — министр иностранных дел. «Странные дела» и «наружные дела» — придуманные в этих книгах названия."]},{"author":"И. Иткин","question":"Какое из этих слов можно понять и как форму именительного падежа единственного числа, и как форму родительного падежа множественного числа?","choices":["<em>май</em>","<em>чай</em>","<em>фей</em>","<em>змей</em>","никакое."],"key":"Г","review":["Два значения формы","Попробуй поставить каждое слово после «вот» и после «нет нескольких». В этих местах нужны разные падежи и числа.","Работают «вот змей» об одном сказочном существе и «нет нескольких змей» о нескольких змеях. «Фей» годится после «несколько», а одна — «фея»."]},{"author":"Л. Фёдорова","question":"У какого слова первая часть обычно прочитывается не так, как у остальных?","choices":["<em>4-угольник</em>","<em>4-томник</em>","<em>4-классник</em>","<em>4-колёсный</em>","<em>4-этажный</em>."],"key":"В","review":["Как прочитать цифру","Произнеси названия фигуры, книги, машины и здания с цифрой 4. Слышится «четырёхугольник», «четырёхтомник», «четырёхколёсный», «четырёхэтажный».","Ученик четвёртого класса — «четвероклассник». Начало «четверо-» отличается от общего для остальных «четырёх-»."]},{"author":"Б. Иомдин","question":"Какое из этих слов образовано не так, как остальные?","choices":["<em>бибикать</em>","<em>ойкать</em>","<em>квакать</em>","<em>плакать</em>","<em>хрюкать</em>."],"key":"Г","review":["Звуки в глаголах","Найди звуки, которые слышатся в глаголах. Сигналит «би-би», человек говорит «ой», лягушка — «ква», свинья — «хрю».","Слово «плакать» означает лить слёзы. Звука «пла», по подражанию которому построен глагол, при плаче нет."]},{"author":"Б. Иомдин","question":"Даны пять словосочетаний. Если поменять в каждом из них слова местами, у четырёх словосочетаний смысл изменится одинаково, а у одного — по-другому. У какого?","choices":["<em>пять раз</em>","<em>четыре штуки</em>","<em>три литра</em>","<em>два часа</em>","<em>один дом</em>."],"key":"Д","review":["Число после слова","Сравни «пять раз» и «раз пять», «два часа» и «часа два». Когда число стоит после названия, его понимают как приблизительное.","Так же работают «штуки четыре» и «литра три». В сочетании «дом один» обычно имеется в виду один-единственный дом, а не приблизительное количество."]},{"author":"И. Рубанов","question":"<em>Сегодня была контрольная. Коле достался первый ... .</em>","choices":["<em>вырянт</em>","<em>варянт</em>","<em>выриант</em>","<em>врянт</em>","<em>вариант</em>."],"key":"Д","review":["Контрольная Коли","На контрольных раздают разные наборы заданий. Такой набор называют вариантом.","Проверь написание «ва-ри-а́нт». В середине две гласные «и» и «а», в первом слоге пишется «а»."]},{"author":"И. Иткин","question":"Сколько в русском языке названий месяцев, у которых в форме родительного падежа единственного числа ударение падает на окончание?","choices":["ни одного","четыре","шесть","семь","двенадцать."],"key":"В","review":["Календарные ударения","Подставь каждый месяц в выражение «до конца …». Послушай, где падает ударение, на часть самого названия или на добавившееся окончание.","Ударение на последнем «я» у января́, февраля́, сентября́, октября́, ноября́ и декабря́. Это шесть месяцев. В «апре́ля» ударение сохраняется на «е»."]},{"author":"Е. Муравенко","question":"В какой паре однокоренные слова связаны между собой по смыслу совсем не так, как в остальных четырёх парах?","choices":["<em>пилить</em> — <em>пила</em>","<em>косить</em> — <em>коса</em>","<em>стрелять</em> — <em>стрела</em>","<em>мести</em> — <em>метла</em>","<em>чертить</em> — <em>черта</em>."],"key":"Д","review":["Чем выполняют действие","Проверь, каким предметом выполняют действие. Пилят пилой, косят косой, стреляют стрелой, метут метлой.","Черта появляется после того, как её начертили. Она результат действия, а чертят, например, карандашом."]},{"author":"Н. Валеева","question":"В одной из систем записи музыки ноты принято обозначать латинскими буквами. Нота <em>до</em> там обозначается буквой C, нота <em>ми</em> — буквой E. А какой буквой обозначается нота <em>соль</em>?","choices":["A","B","V","G","D."],"key":"Г","review":["Буквы для нот","Запиши ноты «до, ре, ми, фа, соль». Из условия известно, что «до» — C, а «ми» — E.","Это порядок латинского алфавита. Между C и E стоит D для «ре», затем F для «фа» и G для «соль»."]},{"author":"П. Аркадьев","question":"Какой из глаголов содержит приставку <em>по-</em>?","choices":["<em>подобрать</em>","<em>подоить</em>","<em>подослать</em>","<em>подорвать</em>","<em>подождать</em>."],"key":"Б","review":["Граница приставки","Сними начало каждого глагола, чтобы найти исходное слово. Получатся «брать», «доить», «слать», «рвать» и «ждать».","В «подоить» буква д осталась в слове «доить», поэтому приставка «по-». У остальных начало «под-» или «подо-»."]},{"author":"И. Рубанов","question":"Выполняя задание, рабочий уложился в 5 часов. Это означает, что он потратил на выполнение задания","choices":["ровно 5 часов","меньше 5 часов","больше 5 часов","не меньше 5 часов","не больше 5 часов."],"key":"Д","review":["Пять часов на работу","Представь, что пять часов — срок, к концу которого рабочий должен закончить. Он успевает, если заканчивает раньше или в самый конец срока.","Если он работал четыре часа или ровно пять, он уложился. Оба случая охватывает выражение «не больше пяти часов»."]},{"author":"С. Бурлак","question":"Вася решил сочинить рассказ. Вот все предложения из этого рассказа:\n1) <em>А это оказался илистый прыгун.</em>\n2) <em>Смотрю — на песке лежит рыба!</em>\n3) <em>Шёл я по берегу.</em>\n4) <em>Он любит по суше ползать.</em>\n5) <em>Я думал, её волной выбросило.</em>\nВ каком порядке они должны идти?","choices":["3, 2, 1, 5, 4","3, 2, 5, 1, 4","3, 4, 2, 5, 1","5, 1, 3, 4, 2","2, 4, 5, 3, 1."],"key":"Б","review":["Рыба на берегу","Начни с места действия, затем назови находку. Герой шёл по берегу и заметил рыбу на песке.","Сначала он предполагает, что её выбросило волной. Потом узнаёт илистого прыгуна и объясняет его привычку ползать. Порядок 3, 2, 5, 1, 4."]},{"author":"К. Гилярова","question":"«Страна Вообразилия» Бориса Заходера начинается с ПРИДИСЛОВИЯ, а заканчивается … .","choices":["УЙДИСЛОВИЕМ","ЗАЙДИСЛОВИЕМ","ПОСЛЕСЛОВИЕМ","МНОГОСЛОВИЕМ","ЭПИЛОГОМ."],"key":"А","review":["Начало Вообразилии","Заходер переделал «предисловие» в «придисловие», чтобы в названии слышалось приглашение «приди».","В финале герой или читатель уходит. Возьми противоположное «уйди» и дострой по образцу «уйдисловием»."]},{"author":"К. Кноп","question":"<em>Цены растут как на ... .</em>","choices":["<em>бобах</em>","<em>грибах</em>","<em>дрожжах</em>","<em>подбор</em>","<em>снежном</em> <em>коме</em>."],"key":"В","review":["Рост цен","Цены, которые быстро увеличиваются, сравнивают с тестом. Вспомни, что позволяет тесту быстро подняться.","Когда в тесте есть дрожжи, в нём образуются пузырьки и оно растёт. Отсюда выражение «растёт как на дрожжах»."]},{"author":"С. Бурлак","question":"В каком слове есть звонкий согласный звук?","choices":["<em>хочет</em>","<em>шьёт</em>","<em>пищит</em>","<em>уцепится</em>","ни в одном из этих слов звонких согласных звуков нет."],"key":"Б","review":["Звонкий звук","Произнеси слова по звукам. В «хочет» согласные [х], [ч’], [т], в «пищит» — [п’], [щ’], [т], в «уцепится» — [ц], [п’] и звук [ц] на месте «тс». Все глухие.","В слове «шьёт» после разделительного мягкого знака буква ё даёт [й’] и [о]. Согласный [й’] звонкий."]},{"author":"Е. Бикмаев","question":"Вот три слова на придуманном «кирпичном» языке и их переводы на русский язык: <em>сасапосог</em> — «сапог»; <em>ососаса</em> — «оса»; <em>дасар</em> — «дар». Как переводится на «кирпичный» язык слово <em>утёнок</em>?","choices":["<em>усутёсёнок</em>","<em>утёсёносок</em>","<em>усутёносок</em>","<em>усутёсёносок</em>","<em>усутёсёноксок.</em>"],"key":"Г","review":["Кирпичный язык","Сравни «дар» и «да-с-а-р», «оса» и «о-с-о-са-с-а». После каждой исходной гласной вставлены «с» и ещё раз та же гласная.","В «утёнок» повтори у, ё и о с буквой с между повторами. Получится «у-су-тё-сё-но-со-к», то есть «усутёсёносок»."]},{"author":"К. Гилярова","question":"Когда у свиньи рождаются поросята, говорят, что она <em>опоросилась</em>. А про корову — что она <em>отелилась</em>. А как правильно сказать про только что родившую лошадь?","choices":["<em>олошадилась</em>","<em>оконилась</em>","<em>ожеребятилась</em>","<em>ожеребёнилась</em>","<em>ожеребилась</em>."],"key":"Д","review":["Малыш лошади","В слове «опоросилась» слышно название поросёнка, а в «отелилась» — название телёнка. Вспомни имя детёныша лошади.","От «жеребёнок» возьми часть «жереб-». Со словом «ожеребилась» получится такая же связь, как в примерах."]},{"author":"А. Сомин","question":"По-белорусски <em>весна</em> — <em>вясна</em>, а <em>сестра</em> — <em>сястра</em>. Для чего используется устройство, которое по-белорусски называется <em>лядо́ўня</em>? (<em>ў</em> обозначает звук, средний между <em>в</em> и <em>у</em>)","choices":["для приготовления пищи","для мытья посуды","для стирки","для глажки","для хранения продуктов."],"key":"Д","review":["Белорусское устройство","По парам «весна — вясна» и «сестра — сястра» догадайся, что русскому е может соответствовать белорусское я. Сопоставь «лядоўня» с русским «ледовня».","В слове «ледовня» слышно «лёд». Это место, где держат продукты в холоде, чтобы они дольше хранились."]},{"author":"Б. и М. Иомдины","question":"В стихотворении Ренаты Мухи «Улитка» есть такие строки:\n«<em>Потом обратился</em>\n<em>С вопросом к прохожим</em>\n<em>И всем пролета-</em>\n<em>И ползающим тоже</em>».\nКакое слово здесь читается не так, как обычно?","choices":["<em>потом</em>","<em>обратился</em>","<em>вопросом</em>","<em>прохожим</em>","<em>ползающим</em>."],"key":"Д","review":["Стихи об улитке","Соедини обрезанное «пролета-» с пропущенным окончанием. В обычном слове «пролета́ющим» ударение падает на «а».","Прочитай «пролета́- и полза́ющим» так, чтобы оба слова делили конец «-ющим» и ударение падало на «а» перед ним. В обычной речи сказали бы «по́лзающим»."]},{"author":"Е. Муравенко","question":"Какое слово надо вписать вместо многоточия, чтобы в получившейся паре слова были связаны по смыслу так же, как в двух предыдущих?\n<em>Стоять — ставить</em>, <em>висеть — вешать</em>, <em>лежать</em> — … .","choices":["<em>класть</em>","<em>положить</em>","<em>полежать</em>","<em>лечь</em>","<em>ложиться</em>."],"key":"А","review":["Изменить положение","Два первых глагола, «стоять» и «висеть», называют положение предмета. «Ставить» и «вешать» называют действие, которое приводит к такому положению.","Когда предмет кладут на полку, он начинает лежать. Поэтому пара — «лежать — класть». «Класть», как «ставить» и «вешать», называет действие без указания на его завершение."]},{"author":"А. Лопухина","question":"В XIX веке знаменитый филолог Яков Грот разделил все согласные звуки русского языка на <strong>дебелые</strong> (как в слове <em>желток</em>) и <strong>тонкие</strong> (как в слове <em>синий</em>). А сейчас мы называем эти согласные ... .","choices":["парные и непарные","глухие и звонкие","мягкие и твёрдые","звонкие и глухие","твёрдые и мягкие."],"key":"Д","review":["Согласные у Грота","Произнеси согласные слова «желток». [ж], [л], [т] и [к] звучат твёрдо.","В «синий» слышатся мягкие [с’], [н’] и [й’]. Поэтому дебелые согласные у Грота — твёрдые, а тонкие — мягкие."]},{"author":"К. Кноп","question":"<em>Воскресенье</em>, <em>вторник</em>, <em>понедельник</em>, <em>пятница</em>, ... Каким должен быть порядок дней недели в конце этого ряда?","choices":["<em>среда</em>, <em>суббота</em>, <em>четверг</em>","<em>суббота</em>, <em>среда</em>, <em>четверг</em>","<em>среда</em>, <em>четверг</em>, <em>суббота</em>","<em>четверг</em>, <em>среда</em>, <em>суббота</em>","<em>четверг</em>, <em>суббота</em>, <em>среда</em>."],"key":"А","review":["Ряд дней недели","Сравни первые буквы названий. Воскресенье и вторник начинаются с В, а понедельник и пятница с П. Внутри пар тоже соблюдён алфавитный порядок, «во» перед «вт», «по» перед «пя».","Остались «среда», «суббота», «четверг». С идёт раньше Ч, а «ср» раньше «су», поэтому порядок именно такой."]},{"author":"Е. Муравенко","question":"Даны слова родственного русскому хорватского языка с переводом на русский: ima — <em>имеет</em>, imaju — <em>имеют</em>, gledam — <em>смотрю</em>, gledaju — <em>смотрят</em>, pada — <em>падает</em>, padamo — <em>падаем</em>. Как будет по-хорватски <em>имеем</em>, <em>смотрит</em>, <em>падаю</em>?","choices":["imamo, gleda, padam","imam, gleda, padaju","imamo, gleda, padaju","imamo, gledat, padam","imam, gledat, pada."],"key":"А","review":["Хорватские глаголы","Сопоставь «pada — падает» и «padamo — падаем». Для «мы» добавляется «-mo», поэтому «имеем» — «imamo».","Для «он» к «gleda» ничего не нужно добавлять, как к «ima» и «pada». Для «я» нужен конец «-m», как в «gledam», поэтому «падаю» — «padam»."]}]), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
